  1→// Package summarize provides AI-powered summarization of development sessions.
  2→package summarize
  3→
  4→import (
  5→	"context"
  6→	"encoding/json"
  7→	"errors"
  8→	"fmt"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
 13→	"github.com/entireio/cli/cmd/entire/cli/agent/opencode"
 14→	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
 15→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 16→)
 17→
 18→// GenerateFromTranscript generates a summary from raw transcript bytes.
 19→// This is the shared implementation used by both explain --generate and auto-summarize.
 20→//
 21→// Parameters:
 22→//   - ctx: context for cancellation
 23→//   - transcriptBytes: raw transcript bytes (JSONL or JSON format depending on agent)
 24→//   - filesTouched: list of files modified during the session
 25→//   - agentType: the agent type to determine transcript format
 26→//   - generator: summary generator to use (if nil, uses default ClaudeGenerator)
 27→//
 28→// Returns nil, error if transcript is empty or cannot be parsed.
 29→func GenerateFromTranscript(ctx context.Context, transcriptBytes []byte, filesTouched []string, agentType agent.AgentType, generator Generator) (*checkpoint.Summary, error) {
 30→	if len(transcriptBytes) == 0 {
 31→		return nil, errors.New("empty transcript")
 32→	}
 33→
 34→	// Build condensed transcript for summarization
 35→	condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
 36→	if err != nil {
 37→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 38→	}
 39→	if len(condensed) == 0 {
 40→		return nil, errors.New("transcript has no content to summarize")
 41→	}
 42→
 43→	input := Input{
 44→		Transcript:   condensed,
 45→		FilesTouched: filesTouched,
 46→	}
 47→
 48→	// Use default generator if none provided
 49→	if generator == nil {
 50→		generator = &ClaudeGenerator{}
 51→	}
 52→
 53→	summary, err := generator.Generate(ctx, input)
 54→	if err != nil {
 55→		return nil, fmt.Errorf("failed to generate summary: %w", err)
 56→	}
 57→
 58→	return summary, nil
 59→}
 60→
 61→// Generator generates checkpoint summaries using an LLM.
 62→type Generator interface {
 63→	// Generate creates a summary from checkpoint data.
 64→	// Returns the generated summary or an error if generation fails.
 65→	Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
 66→}
 67→
 68→// Input contains condensed checkpoint data for summarization.
 69→type Input struct {
 70→	// Transcript is the condensed transcript entries
 71→	Transcript []Entry
 72→
 73→	// FilesTouched are the files modified during the session
 74→	FilesTouched []string
 75→}
 76→
 77→// EntryType represents the type of a transcript entry.
 78→type EntryType string
 79→
 80→const (
 81→	// EntryTypeUser indicates a user prompt entry.
 82→	EntryTypeUser EntryType = "user"
 83→	// EntryTypeAssistant indicates an assistant response entry.
 84→	EntryTypeAssistant EntryType = "assistant"
 85→	// EntryTypeTool indicates a tool call entry.
 86→	EntryTypeTool EntryType = "tool"
 87→)
 88→
 89→// Entry represents one item in the condensed transcript.
 90→type Entry struct {
 91→	// Type is the entry type (user, assistant, tool)
 92→	Type EntryType
 93→
 94→	// Content is the text content for user/assistant entries
 95→	Content string
 96→
 97→	// ToolName is the name of the tool (for tool entries)
 98→	ToolName string
 99→
100→	// ToolDetail is a description or file path (for tool entries)
101→	ToolDetail string
102→}
103→
104→// minimalDetailTools lists tools that should show only essential details in summaries.
105→// These tools often have verbose outputs that don't add value to summarization.
106→// The detail shown is typically just a path, URL, or identifier rather than full content.
107→var minimalDetailTools = map[string]bool{
108→	"Skill":    true, // Show skill name only, not loaded content
109→	"Read":     true, // Show file path only, not file contents
110→	"WebFetch": true, // Show URL only, not fetched content
111→}
112→
113→// BuildCondensedTranscriptFromBytes parses transcript bytes and extracts a condensed view.
114→// This is a convenience function that combines parsing and condensing.
115→// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
116→func BuildCondensedTranscriptFromBytes(content []byte, agentType agent.AgentType) ([]Entry, error) {
117→	switch agentType {
118→	case agent.AgentTypeGemini:
119→		return buildCondensedTranscriptFromGemini(content)
120→	case agent.AgentTypeOpenCode:
121→		return buildCondensedTranscriptFromOpenCode(content)
122→	case agent.AgentTypeClaudeCode, agent.AgentTypeUnknown:
123→		// Claude format - fall through to shared logic below
124→	}
125→	// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
126→	lines, err := transcript.ParseFromBytes(content)
127→	if err != nil {
128→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
129→	}
130→	return BuildCondensedTranscript(lines), nil
131→}
132→
133→// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
134→func buildCondensedTranscriptFromGemini(content []byte) ([]Entry, error) {
135→	geminiTranscript, err := geminicli.ParseTranscript(content)
136→	if err != nil {
137→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
138→	}
139→
140→	var entries []Entry
141→	for _, msg := range geminiTranscript.Messages {
142→		switch msg.Type {
143→		case geminicli.MessageTypeUser:
144→			if msg.Content != "" {
145→				entries = append(entries, Entry{
146→					Type:    EntryTypeUser,
147→					Content: msg.Content,
148→				})
149→			}
150→		case geminicli.MessageTypeGemini:
151→			// Add assistant content
152→			if msg.Content != "" {
153→				entries = append(entries, Entry{
154→					Type:    EntryTypeAssistant,
155→					Content: msg.Content,
156→				})
157→			}
158→			// Add tool calls
159→			for _, tc := range msg.ToolCalls {
160→				entries = append(entries, Entry{
161→					Type:       EntryTypeTool,
162→					ToolName:   tc.Name,
163→					ToolDetail: extractGenericToolDetail(tc.Args),
164→				})
165→			}
166→		}
167→	}
168→
169→	return entries, nil
170→}
171→
172→// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
173→func buildCondensedTranscriptFromOpenCode(content []byte) ([]Entry, error) {
174→	session, err := opencode.ParseExportSession(content)
175→	if err != nil {
176→		return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
177→	}
178→	if session == nil {
179→		return nil, nil
180→	}
181→
182→	var entries []Entry
183→	for _, msg := range session.Messages {
184→		switch msg.Info.Role {
185→		case "user":
186→			text := extractTextFromOpenCodeParts(msg.Parts)
187→			if text != "" {
188→				entries = append(entries, Entry{
189→					Type:    EntryTypeUser,
190→					Content: text,
191→				})
192→			}
193→		case "assistant":
194→			text := extractTextFromOpenCodeParts(msg.Parts)
195→			if text != "" {
196→				entries = append(entries, Entry{
197→					Type:    EntryTypeAssistant,
198→					Content: text,
199→				})
200→			}
201→			for _, part := range msg.Parts {
202→				if part.Type == "tool" && part.State != nil {
203→					entries = append(entries, Entry{
204→						Type:       EntryTypeTool,
205→						ToolName:   part.Tool,
206→						ToolDetail: extractGenericToolDetail(part.State.Input),
207→					})
208→				}
209→			}
210→		}
211→	}
212→
213→	return entries, nil
214→}
215→
216→// extractTextFromOpenCodeParts extracts text content from OpenCode message parts.
217→func extractTextFromOpenCodeParts(parts []opencode.Part) string {
218→	var texts []string
219→	for _, part := range parts {
220→		if part.Type == "text" && part.Text != "" {
221→			texts = append(texts, part.Text)
222→		}
223→	}
224→	return strings.Join(texts, "\n")
225→}
226→
227→// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
228→// Checks common fields in order of preference. Used by both OpenCode and Gemini condensation.
229→func extractGenericToolDetail(input map[string]interface{}) string {
230→	for _, key := range []string{"description", "command", "filePath", "file_path", "path", "pattern"} {
231→		if v, ok := input[key].(string); ok && v != "" {
232→			return v
233→		}
234→	}
235→	return ""
236→}
237→
238→// BuildCondensedTranscript extracts a condensed view of the transcript.
239→// It processes user prompts, assistant responses, and tool calls into
240→// a simplified format suitable for LLM summarization.
241→func BuildCondensedTranscript(lines []transcript.Line) []Entry {
242→	var entries []Entry
243→
244→	for _, line := range lines {
245→		switch line.Type {
246→		case transcript.TypeUser:
247→			if entry := extractUserEntry(line); entry != nil {
248→				entries = append(entries, *entry)
249→			}
250→		case transcript.TypeAssistant:
251→			assistantEntries := extractAssistantEntries(line)
252→			entries = append(entries, assistantEntries...)
253→		}
254→	}
255→
256→	return entries
257→}
258→
259→// skillContentPrefix identifies user messages that are skill content injections.
260→// These are injected after a Skill tool call and contain the full skill instructions.
261→const skillContentPrefix = "Base directory for this skill:"
262→
263→// extractUserEntry extracts a user entry from a transcript line.
264→// Returns nil if the line doesn't contain a valid user prompt or is skill content.
265→func extractUserEntry(line transcript.Line) *Entry {
266→	content := transcript.ExtractUserContent(line.Message)
267→	if content == "" {
268→		return nil
269→	}
270→
271→	// Skip skill content injections - these are verbose skill instructions
272→	// injected as user messages after Skill tool invocations in Claude Code.
273→	// The prefix "Base directory for this skill:" is added by the superpowers
274→	// plugin when loading skill content. This filtering reduces transcript noise
275→	// since skill content is documentation, not user intent.
276→	if strings.HasPrefix(content, skillContentPrefix) {
277→		return nil
278→	}
279→
280→	return &Entry{
281→		Type:    EntryTypeUser,
282→		Content: content,
283→	}
284→}
285→
286→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
287→func extractAssistantEntries(line transcript.Line) []Entry {
288→	var msg transcript.AssistantMessage
289→	if err := json.Unmarshal(line.Message, &msg); err != nil {
290→		return nil
291→	}
292→
293→	var entries []Entry
294→
295→	for _, block := range msg.Content {
296→		switch block.Type {
297→		case transcript.ContentTypeText:
298→			if block.Text != "" {
299→				entries = append(entries, Entry{
300→					Type:    EntryTypeAssistant,
301→					Content: block.Text,
302→				})
303→			}
304→		case transcript.ContentTypeToolUse:
305→			var input transcript.ToolInput
306→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
307→
308→			detail := extractToolDetail(block.Name, input)
309→
310→			entries = append(entries, Entry{
311→				Type:       EntryTypeTool,
312→				ToolName:   block.Name,
313→				ToolDetail: detail,
314→			})
315→		}
316→	}
317→
318→	return entries
319→}
320→
321→// extractToolDetail extracts an appropriate detail string for a tool call.
322→// For tools in minimalDetailTools, only essential identifiers are shown.
323→// For other tools, the full detail chain is used.
324→func extractToolDetail(toolName string, input transcript.ToolInput) string {
325→	// For minimal detail tools, extract only the essential identifier
326→	if minimalDetailTools[toolName] {
327→		switch toolName {
328→		case "Skill":
329→			return input.Skill
330→		case "Read":
331→			if input.FilePath != "" {
332→				return input.FilePath
333→			}
334→			return input.NotebookPath
335→		case "WebFetch":
336→			return input.URL
337→		}
338→	}
339→
340→	// For other tools, use the full detail chain
341→	if input.Description != "" {
342→		return input.Description
343→	}
344→	if input.Command != "" {
345→		return input.Command
346→	}
347→	if input.FilePath != "" {
348→		return input.FilePath
349→	}
350→	if input.NotebookPath != "" {
351→		return input.NotebookPath
352→	}
353→	return input.Pattern
354→}
355→
356→// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
357→// The format is:
358→//
359→//	[User] user prompt here
360→//
361→//	[Assistant] assistant response here
362→//
363→//	[Tool] ToolName: description or file path
364→func FormatCondensedTranscript(input Input) string {
365→	var sb strings.Builder
366→
367→	for i, entry := range input.Transcript {
368→		if i > 0 {
369→			sb.WriteString("\n")
370→		}
371→
372→		switch entry.Type {
373→		case EntryTypeUser:
374→			sb.WriteString("[User] ")
375→			sb.WriteString(entry.Content)
376→			sb.WriteString("\n")
377→		case EntryTypeAssistant:
378→			sb.WriteString("[Assistant] ")
379→			sb.WriteString(entry.Content)
380→			sb.WriteString("\n")
381→		case EntryTypeTool:
382→			sb.WriteString("[Tool] ")
383→			sb.WriteString(entry.ToolName)
384→			if entry.ToolDetail != "" {
385→				sb.WriteString(": ")
386→				sb.WriteString(entry.ToolDetail)
387→			}
388→			sb.WriteString("\n")
389→		}
390→	}
391→
392→	if len(input.FilesTouched) > 0 {
393→		sb.WriteString("\n[Files Modified]\n")
394→		for _, file := range input.FilesTouched {
395→			fmt.Fprintf(&sb, "- %s\n", file)
396→		}
397→	}
398→
399→	return sb.String()
400→}
