203→func TestBuildCondensedTranscript_SkipsSkillContentInjection(t *testing.T) {
204→	skillContent := `Base directory for this skill: /Users/alex/.claude/plugins/cache/superpowers/4.1.1/skills/brainstorming
205→
206→# Brainstorming Ideas Into Designs
207→
208→## Overview
209→
210→This is verbose skill content that should not appear in summaries...`
211→
212→	lines := []transcript.Line{
213→		{
214→			Type: "user",
215→			UUID: "user-1",
216→			Message: mustMarshal(t, transcript.UserMessage{
217→				Content: "Invoke the superpowers:brainstorming skill",
218→			}),
219→		},
220→		{
221→			Type: "assistant",
222→			UUID: "assistant-1",
223→			Message: mustMarshal(t, transcript.AssistantMessage{
224→				Content: []transcript.ContentBlock{
225→					{Type: "tool_use", Name: "Skill", Input: mustMarshal(t, transcript.ToolInput{Skill: "superpowers:brainstorming"})},
226→				},
227→			}),
228→		},
229→		{
230→			Type: "user",
231→			UUID: "user-2",
232→			Message: mustMarshal(t, transcript.UserMessage{
233→				Content: skillContent, // This should be filtered out
234→			}),
235→		},
236→		{
237→			Type: "user",
238→			UUID: "user-3",
239→			Message: mustMarshal(t, transcript.UserMessage{
240→				Content: "Now help me brainstorm a feature",
241→			}),
242→		},
243→	}
244→
245→	entries := BuildCondensedTranscript(lines)
246→
247→	// Should have: user prompt, tool call, user prompt (NOT the skill content)
248→	if len(entries) != 3 {
249→		t.Fatalf("expected 3 entries (skill content filtered), got %d", len(entries))
250→	}
251→
252→	// Verify the skill content was filtered
253→	for _, entry := range entries {
254→		if entry.Type == EntryTypeUser && strings.Contains(entry.Content, "Base directory for this skill") {
255→			t.Error("skill content injection should have been filtered out")
256→		}
257→	}
258→
259→	// Verify the real user messages are present
260→	if entries[0].Content != "Invoke the superpowers:brainstorming skill" {
261→		t.Errorf("first user message wrong: %s", entries[0].Content)
262→	}
263→	if entries[2].Content != "Now help me brainstorm a feature" {
264→		t.Errorf("last user message wrong: %s", entries[2].Content)
265→	}
266→}
